mapper.select:
SELECT v.id as videoId, uv.id as extractId, v.platform_type as platformType, v.platform_video_id as platformVideoId, v.title as videoTitle, v.cover_url as videoCover, v.video_url as videoUrl, v.duration as duration, v.publish_time as publishTime, r.influencer_nickname as influencerNickname, r.influencer_platform_user_id as influencerPlatformUserId, r.influencer_avatar as influencerAvatar, r.influencer_followers_count as followersCount, v.like_count as likeCount, v.comment_count as commentCount, v.share_count as shareCount, v.collect_count as collectCount, COALESCE(uv.extract_status, 0) as extractStatus FROM tb_video_hot_search_relation r LEFT JOIN tb_video_info v ON r.video_id = v.id LEFT JOIN tb_video_user_video uv ON ( uv.video_id = v.id
AND uv.tenant_id = #{tenantId} AND uv.source_type = 4 AND uv.is_deleted = 0 ) WHERE r.snapshot_id = #{queryBo.snapshotId} AND r.is_deleted = 0 AND v.is_deleted = 0
AND v.like_count >= #{queryBo.likeCount}
AND v.comment_count >= #{queryBo.commentCount}
AND v.share_count >= #{queryBo.shareCount}
AND v.collect_count >= #{queryBo.collectCount}
AND v.publish_time >= #{queryBo.publishStartTime}
AND v.publish_time <= #{queryBo.publishEndTime}
AND v.duration >= #{queryBo.durationStartNumber}
AND v.duration <= #{queryBo.durationEndNumber}
ORDER BY v.like_count ASC DESC
ORDER BY v.comment_count ASC DESC
ORDER BY v.share_count ASC DESC
ORDER BY v.collect_count ASC DESC
ORDER BY r.sort_order DESC
